package com.athaan.app.data

/**
 * A dhikr: its text, how many times it is said, an optional title (e.g. "آية الكرسي") and
 * its virtue from the hadith.
 */
data class Dhikr(val text: String, val count: Int, val note: String = "", val virtue: String = "")

enum class AdhkarSet(val ar: String, val en: String, val shortAr: String, val shortEn: String) {
    MORNING("أذكار الصباح", "Morning adhkar", "الصباح", "Morning"),
    EVENING("أذكار المساء", "Evening adhkar", "المساء", "Evening"),
    AFTER_PRAYER("أذكار بعد الصلاة", "After prayer", "بعد الصلاة", "After prayer"),
    SLEEP("أذكار النوم", "Before sleep", "النوم", "Sleep"),
}

